from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tree):
    # LeetCode list -> linked nodes. Each popped parent takes the next two slots.
    if not tree or tree[0] is None:
        return None
    root = Node(tree[0])
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        node = queue.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = Node(tree[i])
            queue.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = Node(tree[i])
            queue.append(node.right)
        i += 1
    return root

def subtree_values(node):
    values = []
    stack = [node] if node is not None else []
    while stack:
        cur = stack.pop()
        values.append(cur.val)
        for child in (cur.left, cur.right):
            if child is not None:
                stack.append(child)
    return values

def solution(tree):
    # Check every node against every value in both subtrees: O(n^2) on a chain.
    root = build(tree)
    stack = [root] if root is not None else []
    while stack:
        node = stack.pop()
        if any(v >= node.val for v in subtree_values(node.left)):
            return False
        if any(v <= node.val for v in subtree_values(node.right)):
            return False
        for child in (node.left, node.right):
            if child is not None:
                stack.append(child)
    return True
